-- Kleros event history, Jan 2025 to Nov 2026, reconciled from the open-web, X/LinkedIn/Luma and YouTube sweeps
-- (research files in kleros-events/research, 26 Oct 2026). Review table: kleros-events/research/event-history-review.md.
--
-- Safe to run more than once, and on the live database that already holds the 8 events of 2026-10-real-events.sql
-- (their slugs are kept). Events are upserted by slug. Materials are reconciled by (event, url): URL-only rows
-- (no file_path, pdf_path or audio_path) of kind video, link, social or slides that are not in the list below are
-- removed, unless a transcript is attached to them; listed rows are updated in place, so their ids, transcripts
-- and watch progress survive; missing rows are added. Uploaded recordings and files are never touched, nor are
-- questions, RSVPs, event_team, is_example or created_by.
-- Only confirmed events are listed; unconfirmed ones were dropped on 26 Oct 2026 (see 2026-10-drop-unconfirmed.sql).

begin;

on conflict (slug) do update set
  title = excluded.title,
  kleros_role = excluded.kleros_role,
  organizer = excluded.organizer,
  event_type = excluded.event_type,
  starts_on = excluded.starts_on,
  ends_on = excluded.ends_on,
  start_time = excluded.start_time,
  timezone = excluded.timezone,
  city = excluded.city,
  country = excluded.country,
  region = excluded.region,
  venue = excluded.venue,
  url = excluded.url,
  cover_path = excluded.cover_path,
  description = excluded.description,
  topics = excluded.topics,
  recap = excluded.recap,
  status = excluded.status,
  updated_at = now();

-- the reconciled materials: (slug, kind, title, speaker, url, n)
create temp table _m (slug text, kind material_kind, title text, speaker text, url text, n int) on commit drop;

create temp table _ev on commit drop as
  select id, slug from events where slug in ('externado-legal-innovation-workshop-2025', 'curation-webinar-2025', 'merge-buenos-aires-2025', 'from-idea-to-impact-legaltech-workshop-2025', 'md4dj-kings-college-london-2025', 'odr-forum-london-2025', 'university-of-manchester-talk-2025', 'stanford-blockchain-governance-summit-2025', 'crypto-arbitration-forum-zurich-2025', 'eth-cluj-2025', 'ethcc-8-cannes-2025', 'ierr-demo-day-2025', 'abogados-del-futuro-lima-2025', 'blockchaingov-symposium-paris-2025', 'devconnect-legal-scholars-program-2025', 'argentina-onchain-edge-city-patagonia-2025', 'governance-day-devconnect-2025', 'entity-onchain-legal-summit-devconnect-2025', 'devconnect-buenos-aires-2025', 'blockchain-oracle-summit-buenos-aires-2025', 'ethcon-argentina-2025', 'arbiverse-buenos-aires-2025', 'funding-the-commons-buenos-aires-2025', 'cifile-webinar-crowds-and-algorithms-2026', 'cryptofriday-lisbon-2026', 'ethcc-9-cannes-2026', 'kleros-ai-uk-tour-kings-college-2026', 'oxford-decentralised-justice-2026', 'edinburgh-algorithms-incentives-law-2026', 'forecast-and-coffee-berkeley-2026', 'dappcon-berlin-2026', 'subtech-buenos-aires-2026', 'ethtaipei-2026', 'banking-the-agent-economy-singapore-2026', '4s-toronto-2026', 'token2049-singapore-2026', 'agentic-finance-summit-the-odds', 'proof-of-humanity-irl', 'the-future-is-tradable', 'who-judges-the-machines-buenos-aires-2026', 'ai-that-acts', 'merge-madrid-2026', 'devcon-8-mumbai', 'onchain-legal-summit-devcon-india', 'ground-truth-mumbai', 'austral-derecho-tecnologia-congreso-2026', 'justicia-descentralizada-en-accion-webinar-2026', 'icc-france-crypto-arbitration-paris-2026', 'colorado-online-dispute-systems-workshop-2026', 'up-guadalajara-masterclass-2025', 'champagnat-blockchain-justicia-mendoza-2025', 'neuchatel-blockchain-dispute-resolution-2025', 'assas-legaltech-class-2025');

-- 1. remove URL-only rows the content scripts created that are no longer in the list (never uploads, never rows with a transcript)
delete from materials m
using _ev e
where m.event_id = e.id
  and m.kind in ('video', 'link', 'social', 'slides')
  and m.file_path is null and m.pdf_path is null and m.audio_path is null
  and not exists (select 1 from _m where _m.slug = e.slug and _m.url = m.url)
  and not exists (select 1 from feed_applied f where f.ok and f.url = m.url)   -- added by the socials feed (0009)
  and (to_regclass('public.transcripts') is null
       or not exists (select 1 from transcripts t where t.material_id = m.id));

-- 2. if an earlier run left two URL-only rows with the same url on one event, keep the oldest
delete from materials m
using materials k, _ev e
where m.event_id = e.id and k.event_id = m.event_id and k.url = m.url and k.id <> m.id
  and m.file_path is null and m.pdf_path is null and m.audio_path is null
  and k.file_path is null and k.pdf_path is null and k.audio_path is null
  and (k.created_at, k.id) < (m.created_at, m.id)
  and (to_regclass('public.transcripts') is null
       or not exists (select 1 from transcripts t where t.material_id = m.id));

-- 3. update listed rows in place (keeps ids, transcripts and watch progress)
update materials m
set kind = _m.kind, title = _m.title, speaker = _m.speaker,
    created_at = date_trunc('day', ev.starts_on::timestamptz) + make_interval(secs => _m.n)
from _m join _ev e on e.slug = _m.slug join events ev on ev.id = e.id
where m.event_id = e.id and m.url = _m.url
  and m.file_path is null and m.pdf_path is null and m.audio_path is null;

-- 4. add the missing ones, ordered as listed
select e.id, _m.kind, _m.title, _m.speaker, _m.url,
       date_trunc('day', ev.starts_on::timestamptz) + make_interval(secs => _m.n)
from _m join _ev e on e.slug = _m.slug join events ev on ev.id = e.id
where not exists (select 1 from materials m where m.event_id = e.id and m.url = _m.url);

commit;

-- summary
select status, count(*) as events,
       (select count(*) from materials m join events e2 on e2.id = m.event_id where e2.status = events.status) as materials,
       (select count(*) from materials m join events e2 on e2.id = m.event_id where e2.status = events.status and m.kind = 'video') as videos
from events group by status order by status;
select e.starts_on, e.slug, e.kleros_role, e.status, count(m.id) as materials
from events e left join materials m on m.event_id = e.id
group by e.id order by e.starts_on, e.slug;
