insert into events (slug, title, kleros_role, organizer, event_type, starts_on, ends_on, start_time, timezone, city, country, region, venue, url, cover_path, description, topics, recap, status) values
('externado-legal-innovation-workshop-2025', 'Workshop on Blockchain, AI and Decentralized Justice (Universidad Externado)', 'speaking', 'Universidad Externado de Colombia', 'Workshop', '2025-02-18', '2025-02-21', null, 'GMT-5', 'Bogotá', 'Colombia', 'Latin America', 'Universidad Externado de Colombia', null, 'https://pbs.twimg.com/media/GkUGrfZWsAAbHtV?format=jpg&name=large', 'Federico Ast gave the masterclass ''Justicia Exponencial: Blockchain e IA en la Resolución de Disputas del Futuro'' on 18 Feb, then led a workshop on blockchain, AI and decentralized justice for the Legal Innovation Specialization at Universidad Externado de Colombia.', '{Legal tech,Arbitration,AI agents}', null, 'published'),
('curation-webinar-2025', 'Exploring Decentralized Justice for Certification and Curation', 'host', 'Kleros', 'Online talk / Space', '2025-02-26', null, null, null, null, null, 'Online', null, null, 'https://i.ytimg.com/vi/S2QowNkxWoc/maxresdefault.jpg', 'A Kleros webinar on using decentralized justice for certification and curation. Federico Ast opened, Fortunato Cinquepalmi presented Scout and Curate, and two guests showed applied cases: Mike Tango Bravo on OpenVino and Denis M. Allgeier on dairy certification.', '{Content moderation,Governance,Arbitration}', null, 'published'),
('merge-buenos-aires-2025', 'MERGE Buenos Aires 2025', 'speaking', 'MERGE', 'Conference', '2025-03-25', null, '16:40', 'GMT-3', 'Buenos Aires', 'Argentina', 'Latin America', 'Palacio Libertad (XBO.com Business Stage)', 'https://www.mmerge.io/merge-buenos-aires-25/events/blockchain-justice-a-new-era-for-transparency-and-trust', 'https://i.ytimg.com/vi/XRrU4VAUMkY/maxresdefault.jpg', 'Federico Ast spoke on the panel ''Blockchain & Justice: A New Era for Transparency and Trust'' with Mario Adaro of the Mendoza Supreme Court, moderated by Javier García Sánchez (IAE). The Spanish-language session covered the Mendoza pilot with Kleros.', '{Legal tech,Arbitration}', null, 'published'),
('from-idea-to-impact-legaltech-workshop-2025', 'From Idea to Impact: A Hands-On Workshop for LegalTech Founders', 'co_host', 'Kleros, King''s Institute for Artificial Intelligence and ArbTech', 'Workshop', '2025-04-23', null, '09:00', 'GMT+1', 'London', 'UK', 'Europe', 'River Room, King''s College London', 'https://www.kcl.ac.uk/events/from-idea-to-impact-launching-your-legaltech-startup', 'https://pbs.twimg.com/media/GpLb0AiXcAAC8C9?format=jpg&name=large', 'Day one of Decentralised Justice Week in London. Kleros co-organized this one-day workshop for legal tech founders with the King''s Institute for Artificial Intelligence and ArbTech, and Federico Ast was an instructor.', '{Legal tech,Community}', null, 'published'),
('md4dj-kings-college-london-2025', 'Mechanism Design for Decentralised Justice: Law in the Age of Crowds and Code', 'co_host', 'King''s Institute for Artificial Intelligence and Kleros', 'Academic', '2025-04-24', null, '09:30', 'GMT+1', 'London', 'UK', 'Europe', 'River Room, Strand Building, King''s College London', 'https://www.kcl.ac.uk/events/mechanism-design-for-decentralised-justice-law-in-the-age-of-crowds-and-code', 'https://storage.ghost.io/c/a6/22/a6222a4e-2e35-45bd-99bd-553de64e73e7/content/images/size/w1200/2025/02/Blog-header_Law-in-the-Age-of-Crowds-and-Code.png', 'A one-day conference (MD4DJ) co-hosted by the King''s Institute for Artificial Intelligence and Kleros. Federico Ast gave the opening remarks and the talk ''Decentralised Justice: A New Legal Paradigm''; William George gave ''The Frontiers of Decentralised Justice: Key Research & Future Challenges'' and joined the peer prediction, social choice and jury selection panels. Rob Dean of the Kleros Supervisory Board sat on the AI and decentralised justice panel.', '{Research,Arbitration,Jurors,AI agents}', null, 'published'),
('odr-forum-london-2025', '25th International Forum on Online Dispute Resolution (ODR 2025)', 'attending', 'ODR Forum / NCTDR', 'Conference', '2025-04-29', '2025-04-30', null, 'GMT+1', 'London', 'UK', 'Europe', 'Old Royal Naval College, Greenwich', 'https://odr.info/?p=176243', 'https://dralab.haifa.ac.il/wp-content/uploads/2025/05/WhatsApp-Image-2025-05-04-at-08.47.24-1.jpeg', 'Federico Ast attended the 25th International Forum on Online Dispute Resolution in Greenwich, the week after Decentralised Justice Week at King''s College London.', '{Arbitration,Legal tech}', null, 'published'),
('university-of-manchester-talk-2025', 'Decentralised Justice: A Future of Commercial Arbitration (University of Manchester)', 'speaking', 'University of Manchester', 'Online talk / Space', '2025-03-18', null, '12:00', 'GMT+0', 'Online', null, 'Online', 'Online webinar', 'https://events.manchester.ac.uk/event/event:e1sg-m7u9b7z2-lgimnm', 'https://events.manchester.ac.uk/dynimg/q-800x800/y1sf-m7u91051-6oyh78.png', 'Federico Ast and Dr Joseph Lee gave the online webinar ''Decentralised Justice: A Future of Commercial Arbitration'', hosted by the University of Manchester.', '{Arbitration,Research}', null, 'published'),
('stanford-blockchain-governance-summit-2025', 'Stanford Blockchain Governance Summit 2025', 'sponsor', 'Stanford University', 'Conference', '2025-05-09', '2025-05-10', null, 'GMT-7', 'Stanford', 'USA', 'North America', null, null, 'https://pbs.twimg.com/media/Gqd8I49WcAAR2p7?format=jpg&name=large', 'Kleros sponsored the two-day Stanford Blockchain Governance Summit, joining ''once again'', and William George was listed among the speakers.', '{Governance,Research}', null, 'published'),
('crypto-arbitration-forum-zurich-2025', '3rd Annual Crypto Arbitration Forum (ASA Local Group Zurich)', 'speaking', 'ASA Local Group Zurich and Crypto Arbitration Forum', 'Panel', '2025-05-20', null, '16:30', 'GMT+2', 'Zurich', 'Switzerland', 'Europe', 'Lenz & Staehelin', 'https://www.swissarbitration.org/events/asa-local-group-zurich-may-2025/', 'https://pbs.twimg.com/media/GrbHZKhXIAAQd5-?format=jpg&name=large', 'Federico Ast was a panelist at the third Crypto Arbitration Forum, ''Arbitrating Crypto and DAO Disputes: Business as Usual, Reform or Revolution?'', with Charlie Morgan, Francesco Di Girolamo, Korinna von Trotha and Raphael Baumann.', '{Arbitration,Legal tech}', null, 'published'),
('eth-cluj-2025', 'ETH Cluj 2025', 'speaking', 'ETH Cluj', 'Conference', '2025-06-26', '2025-06-28', null, 'GMT+3', 'Cluj-Napoca', 'Romania', 'Europe', null, null, 'https://pbs.twimg.com/media/Gr39jWzXAAAfrRU?format=jpg&name=large', 'Clément Lesaege represented Kleros at ETH Cluj in Romania.', '{Prediction markets,Arbitration}', null, 'published'),
('ethcc-8-cannes-2025', 'EthCC[8]', 'speaking', 'Ethereum France', 'Conference', '2025-06-30', '2025-07-03', null, 'GMT+2', 'Cannes', 'France', 'Europe', null, 'https://ethcc.io', 'https://pbs.twimg.com/media/GuxjmqKXAAArvPo?format=jpg&name=large', 'Three Kleros talks on the main programme: William George on ''Peer Prediction and Schelling-Point Oracles'' (30 Jun, Chaplin Stage, plus a roundtable on incentives at the edge), Federico Ast on ''Building Ethical AI: How Decentralized Justice Aligns Artificial Intelligence with Human Values'' (1 Jul) and Clément Lesaege on ''Prediction Markets for Distilled Human Judgement'' (3 Jul). Kleros also ran an EthCC Schelling Game, with token rewards airdropped to participants.', '{AI agents,Prediction markets,Oracles,Research}', null, 'published'),
('ierr-demo-day-2025', 'IERR Demo Day', 'speaking', 'IERR', 'Other', '2025-08-01', null, null, null, null, null, null, null, null, 'https://pbs.twimg.com/media/GxRXm6eW4AEb3dY?format=jpg&name=large', 'William George presented his work at the IERR Demo Day, which was streamed live.', '{Research}', null, 'published'),
('abogados-del-futuro-lima-2025', 'Los Abogados del Futuro 2025 (Universidad del Pacífico)', 'speaking', 'Universidad del Pacífico', 'Academic', '2025-08-12', null, null, 'GMT-5', 'Lima', 'Peru', 'Latin America', 'Universidad del Pacífico', null, 'https://i.ytimg.com/vi/wnJ4BjHKTLE/maxresdefault.jpg', 'Federico Ast gave the session ''Kleros y el nacimiento de la justicia descentralizada'' at Los Abogados del Futuro 2025.', '{Legal tech,Arbitration}', null, 'published'),
('blockchaingov-symposium-paris-2025', 'BlockchainGov Symposium', 'speaking', 'BlockchainGov', 'Academic', '2025-09-25', '2025-09-26', null, 'GMT+2', 'Paris', 'France', 'Europe', null, null, 'https://substack-post-media.s3.amazonaws.com/public/images/1b2dbd40-68cf-4d50-91cd-9477754fa83e_1456x1092.png', 'Federico Ast took part in the BlockchainGov Symposium in Paris.', '{Governance,Research}', null, 'published'),
('devconnect-legal-scholars-program-2025', 'Devconnect Legal Scholars Program', 'speaking', 'Ethereum Foundation', 'Academic', '2025-10-30', null, null, null, null, null, null, null, null, 'https://devconnect.org/og-argentina.png?reset=1', 'Facundo Trotz presented Kleros to the Devconnect Legal Scholars Program ahead of Devconnect Buenos Aires.', '{Legal tech,Arbitration}', null, 'published'),
('argentina-onchain-edge-city-patagonia-2025', 'Argentina Onchain at Edge City Patagonia: Kleros Juror Workshop', 'speaking', 'Argentina Onchain residency (Edge City Patagonia)', 'Workshop', '2025-11-04', null, null, 'GMT-3', 'San Martín de los Andes', 'Argentina', 'Latin America', null, 'https://luma.com/g6uy4h2y', 'https://images.lumacdn.com/event-covers/60/eb925f5a-0462-4c76-80d2-b8989f350c21.jpg', 'Part of the Argentina Onchain residency at Edge City Patagonia. Facundo Trotz and Marcos Pernas Machain ran a workshop in which participants acted as Kleros jurors, and covered public-policy developments for decentralized justice, the Mendoza pilot and the Lemon integration.', '{Jurors,Legal tech,Arbitration}', null, 'published'),
('governance-day-devconnect-2025', 'Governance Day at Devconnect Buenos Aires', 'sponsor', 'SEED Gov, with Blockful, Curia Lab and Metagov', 'Side event', '2025-11-15', null, null, 'GMT-3', 'Buenos Aires', 'Argentina', 'Latin America', 'Pontificia Universidad Católica Argentina (UCA)', 'https://luma.com/vptrr29t', 'https://images.lumacdn.com/event-covers/2m/5d8ac30e-a76f-4bc7-a91e-0f64c9600508.png', 'A Devconnect Buenos Aires side event where Kleros was one of three Main Sponsors, with Blockful and Powerhouse. Alexandre (0xAlex) gave ''Price-Based Futarchy: A Tool for Smarter DAO Decisions'' with Kelvin A. Santos, and Juan Samitier joined the panel ''Beyond the Runway: Designing Sustainable Treasuries with Volatile Tokens''.', '{Governance,Prediction markets}', null, 'published'),
('entity-onchain-legal-summit-devconnect-2025', 'Entity Onchain Legal Summit :: Devconnect 2025', 'co_host', 'Entity, co-hosted by RegistryChain, Kleros, Powerhouse DAO and Otoco', 'Side event', '2025-11-16', null, '16:00', 'GMT-3', 'Buenos Aires', 'Argentina', 'Latin America', 'HIT Polo, Av. Dorrego 3550', 'https://luma.com/8bm7qjc1', 'https://images.lumacdn.com/event-covers/rv/1928e926-6de5-456c-88c9-853420865994.png', 'A Devconnect Buenos Aires side event co-hosted by Kleros. Facundo Trotz gave the talk ''The Justice Layer of DAOs'', on a governance setup combining Kleros, Snapshot, Safe and Gnosis Zodiac, and hosted the panel ''Legal Digital Commons for the Network Age''.', '{Legal tech,Governance,Arbitration}', null, 'published'),
('devconnect-buenos-aires-2025', 'Devconnect Buenos Aires 2025 (Ethereum World''s Fair)', 'booth', 'Ethereum Foundation', 'Conference', '2025-11-17', '2025-11-22', null, 'GMT-3', 'Buenos Aires', 'Argentina', 'Latin America', 'La Rural', 'https://devconnect.org', 'https://pbs.twimg.com/media/G6uY1_PXoAAHc91?format=jpg&name=large', 'Kleros had a booth in the Social District at the Ethereum World''s Fair, showing the Mendoza and Lemon cases, Kleros 2.0 and futarchy. Federico Ast presented ''Decentralized Justice: Kleros'' in the Universidad Austral session of the university track at La Rural. On 17 Nov William George spoke on ''AI and Decentralized Justice'' on the Lightning Stage, and Clément Lesaege and Devansh Mehta gave a talk on DeepFunding and AI prediction markets on the Green stage.', '{Arbitration,Legal tech,Governance,Community}', null, 'published'),
('blockchain-oracle-summit-buenos-aires-2025', 'Blockchain Oracle Summit Buenos Aires', 'speaking', 'Blockchain Oracle Summit', 'Side event', '2025-11-18', null, null, 'GMT-3', 'Buenos Aires', 'Argentina', 'Latin America', 'Ciudad Cultural Konex', null, 'https://pbs.twimg.com/media/G4hM2Ica8AEyupe?format=jpg&name=large', 'A Devconnect Buenos Aires side event. Clément Lesaege gave a talk; the title was not published in the Kleros post.', '{Oracles,Prediction markets}', null, 'published'),
('ethcon-argentina-2025', 'ETHCon Argentina 2025', 'speaking', 'ETHCon Argentina', 'Side event', '2025-11-18', null, null, 'GMT-3', 'Buenos Aires', 'Argentina', 'Latin America', null, null, 'https://pbs.twimg.com/media/G3zN405XYAALEC2?format=jpg&name=large', 'A Devconnect Buenos Aires week conference. Federico Ast was announced as a speaker.', '{Arbitration,Legal tech}', null, 'published'),
('arbiverse-buenos-aires-2025', 'ArbiVerse Buenos Aires', 'sponsor', 'Arbitrum, with Alchemy', 'Side event', '2025-11-19', null, null, 'GMT-3', 'Buenos Aires', 'Argentina', 'Latin America', 'Casa Futuro', 'https://luma.com/ArbiVerseBuenosAires', 'https://images.lumacdn.com/event-covers/ug/dbd2350d-dd2f-425a-be02-0380769b9f76.jpg', 'A Devconnect Buenos Aires side event by Arbitrum. Kleros was a partner and showcased Kleros Enterprise and Kleros 2.0.', '{Arbitration,Smart contracts}', null, 'published'),
('funding-the-commons-buenos-aires-2025', 'Funding the Commons Buenos Aires 2025', 'speaking', 'Funding the Commons', 'Side event', '2025-11-19', null, null, 'GMT-3', 'Buenos Aires', 'Argentina', 'Latin America', 'Fundación Beethoven, Main Stage Auditorium', 'https://www.fundingthecommons.io/events/buenos-aires-2025/', 'https://www.fundingthecommons.io/assets/img/events/2025-11_buenos-aires-conference.jpg', 'A Devconnect Buenos Aires side event. On the RealFi track, Federico Ast held the Spanish-language fireside ''Decentralized Justice in Action: The Kleros - Mendoza Supreme Court Pilot'' with Facundo Trotz and María Fernanda Díaz, magistrate of the Juzgado de Paz y Contravencional de Lavalle.', '{Legal tech,Arbitration}', null, 'published'),
('cifile-webinar-crowds-and-algorithms-2026', 'Between Crowds and Algorithms: Decentralized Justice in the Age of AI', 'co_host', 'Kleros and CIFILE (Canadian Institute for International Law Expertise)', 'Online talk / Space', '2026-02-06', null, '10:00', 'GMT-5', null, null, 'Online', null, null, 'https://pbs.twimg.com/media/HASN6ioXYAM6pxQ?format=jpg&name=large', 'An online webinar co-hosted by Kleros and CIFILE. Federico Ast spoke with Dr. S. Abbas Poorhashemi, President of CIFILE.', '{Legal tech,AI agents,Arbitration}', null, 'published'),
('cryptofriday-lisbon-2026', 'CryptoFriday pwrd by Kleros', 'sponsor', 'The Block Lisboa', 'Meetup', '2026-03-27', null, '18:30', 'GMT+0', 'Lisbon', 'Portugal', 'Europe', 'The Block, Rua Latino Coelho 63', 'https://www.meetup.com/theblock/events/313685347/', 'https://secure.meetupstatic.com/photos/event/5/e/2/highres_533161506.jpeg', 'Kleros powered this CryptoFriday night at The Block Lisboa, with a session introducing Kleros Foresight and its 16-movie prediction market experiment built on Seer. The presenter was not named.', '{Prediction markets,Community}', null, 'published'),
('ethcc-9-cannes-2026', 'EthCC[9]', 'speaking', 'Ethereum France', 'Conference', '2026-03-30', '2026-04-02', null, 'GMT+2', 'Cannes', 'France', 'Europe', 'Palais des Festivals', 'https://ethcc.io', 'https://pbs.twimg.com/media/HE5T160bcAAoIQR?format=jpg&name=large', 'Three Kleros talks on the main programme: Federico Ast on ''Prediction Markets and Decentralized Courts: A New Architecture for Online Justice'' (30 Mar, Redford Stage), Alexandre (0xAlex) on the Kleros DAO futarchy experiment (31 Mar) and William George on ''Voting and Vote Splitting in Crypto-economic Systems'' (31 Mar, Chaplin Stage). Kleros also had a booth on the Green Floor all four days, with juror merch, Foresight credits for EthCC POAP holders and a closing happy hour.', '{Prediction markets,Governance,Arbitration,Research}', null, 'published'),
('kleros-ai-uk-tour-kings-college-2026', 'Kleros + AI UK Tour: King''s College London', 'speaking', 'King''s Institute for Artificial Intelligence, with Kleros', 'Academic', '2026-06-08', null, null, 'GMT+1', 'London', 'UK', 'Europe', 'King''s College London', null, 'https://pbs.twimg.com/amplify_video_thumb/2063003772746395648/img/kSQF-VLLnk-9yM3g.jpg?name=large', 'First stop of the Kleros + AI UK Tour, at the King''s Institute for Artificial Intelligence. Federico Ast and William George spoke; session titles were not published.', '{AI agents,Research,Arbitration}', null, 'published'),
('oxford-decentralised-justice-2026', 'Decentralised Justice: Law in the Digital Age of Crowds and Code', 'co_host', 'Oxford Centre for Socio-Legal Studies and Department of Computer Science, with Kleros', 'Academic', '2026-06-09', null, '14:00', 'GMT+1', 'Oxford', 'UK', 'Europe', 'Arco Roy Griffiths Room, Keble College', 'https://www.law.ox.ac.uk/content/event/decentralised-justice-law-digital-age-crowds-and-code', 'https://storage.ghost.io/c/a6/22/a6222a4e-2e35-45bd-99bd-553de64e73e7/content/images/size/w1200/2026/05/Oxford-Kleros-Workshop_Blog-header.png', 'Second stop of the Kleros + AI UK Tour, co-hosted by Kleros with the University of Oxford. Federico Ast was a panelist in the Law & Society session ''Alternative Dispute Resolution, Digital Environments and Legal Norms'' and moderated the computer science session, where William George spoke on ''Mechanism Design, Game Theory, and AI in Decentralised Justice''.', '{Research,Arbitration,AI agents}', null, 'published'),
('edinburgh-algorithms-incentives-law-2026', 'Algorithms, Incentives, and the Law: Building the Justice Infrastructure for the Era of AI', 'speaking', 'Edinburgh Law School', 'Academic', '2026-06-11', null, '11:30', 'GMT+1', 'Edinburgh', 'UK', 'Europe', 'Teaching Room 3, Old College, University of Edinburgh', 'https://www.law.ed.ac.uk/news-events/events/algorithms-incentives-and-law-building-justice-infrastructure-era-ai', 'https://www.law.ed.ac.uk/sites/default/files/styles/large_image/public/2026-06/Copy%20of%20Event%20Page%20Template%20%2817%29.jpg?itok=SDF7pMdv', 'Third stop of the Kleros + AI UK Tour. Federico Ast and William George gave talks at Edinburgh Law School, with a response by Dr Morshed Mannan.', '{Research,AI agents,Arbitration}', null, 'published'),
('forecast-and-coffee-berkeley-2026', 'Forecast & Coffee', 'co_host', 'Kleros, Precog and Seer', 'Side event', '2026-06-12', null, null, 'GMT-7', 'Berkeley', 'USA', 'North America', 'The Hidden Cafe', null, 'https://pbs.twimg.com/card_img/2113923144817819648/5Yi3VkYv?format=jpg&name=large', 'A Manifest 2026 side event: a no-panels coffee meetup for forecasters the day before Manifest, co-hosted by Kleros with Precog and Seer.', '{Prediction markets,Community}', null, 'published'),
('dappcon-berlin-2026', 'DappCon 2026', 'attending', 'DappCon (Gnosis)', 'Conference', '2026-06-16', null, null, 'GMT+2', 'Berlin', 'Germany', 'Europe', null, 'https://dappcon.io', 'https://framerusercontent.com/images/379eGLC7enRHiHMk4Kt0j6m5qlQ.jpg', 'During Berlin Blockchain Week, Fortunato Cinquepalmi, JB (JayBuidl), Nick, Clément Lesaege and Alexandre (0xAlex) attended DappCon.', '{Community,Smart contracts}', null, 'published'),
('subtech-buenos-aires-2026', 'SubTech 2026', 'speaking', 'SubTech with Universidad de San Andrés (CPINN)', 'Academic', '2026-06-24', '2026-06-26', null, 'GMT-3', 'Buenos Aires', 'Argentina', 'Latin America', 'Universidad de San Andrés', null, 'https://pbs.twimg.com/media/HMA5JM1XQAAAqnQ?format=jpg&name=large', 'The Substantive Technology in Legal Education and Practice conference, held in Latin America for the first time with Federico Ast''s help. Federico Ast sat on the ''AI and Justice'' panel with Amy Schmitz, Mario Adaro and Jorge Balmaceda Hoyos and presented Kleros research on LLMs as jurors and arbitrators.', '{Legal tech,AI agents,Research}', null, 'published'),
('ethtaipei-2026', 'ETHTaipei 2026', 'speaking', 'ETHTaipei', 'Conference', '2026-09-13', '2026-09-14', null, 'GMT+8', 'Taipei', 'Taiwan', 'Asia', 'POPOP Taipei', 'https://ethtaipei.org/', 'https://pbs.twimg.com/media/HRWXmt9aUAAL8ZZ?format=jpg&name=large', 'Clément Lesaege gave the talk ''From Event Markets to Information Finance'', on prediction markets built first to produce information and guide decisions.', '{Prediction markets,Oracles}', null, 'published'),
('banking-the-agent-economy-singapore-2026', 'Banking the Agent Economy', 'sponsor', 'Estonian Business Hub, Compass Labs and Yellow Card', 'Side event', '2026-10-06', null, '14:30', 'GMT+8', 'Singapore', 'Singapore', 'Asia', 'Estonian Business Hub, 18 Robinson Rd', 'https://luma.com/3cvlquah', 'https://images.lumacdn.com/uploads/j3/78ccb07f-4747-41c2-a940-5d89f63e219d.png', 'Kleros was a supporting partner of this TOKEN2049 Singapore side event, hosted at the Estonian Business Hub. No Kleros speaker was on the agenda.', '{AI agents,DeFi}', null, 'published'),
('4s-toronto-2026', '4S 2026: Protocols, Among Humans and Machines', 'speaking', 'Society for Social Studies of Science', 'Academic', '2026-10-07', null, null, 'GMT-4', 'Toronto', 'Canada', 'North America', null, 'https://4sonline.org/about_the_conference_toronto.php', 'https://4sonline.org/photos/ConferencePageBannerToronto2026_12092025192656.JPG', 'At the 50th annual meeting of the Society for Social Studies of Science, William George presented ''When Decentralised Justice Meets Artificial Intelligence: Law in the Age of Crowds and Code'' on a panel organized by Nathan Schneider, with Helena Rong, Andi Argast and Vincent Charlebois.', '{Research,AI agents,Jurors}', null, 'published'),
('token2049-singapore-2026', 'TOKEN2049 Singapore', 'attending', 'TOKEN2049', 'Conference', '2026-10-07', '2026-10-08', null, 'GMT+8', 'Singapore', 'Singapore', 'Asia', 'Marina Bay Sands', 'https://www.asia.token2049.com', 'https://pbs.twimg.com/amplify_video_thumb/2107743882951979008/img/C_rXCTclx_cOI15h.jpg?name=large', 'The Kleros team, including Clément Lesaege and Wei Wei Ooi, was in Singapore for TOKEN2049 week. Kleros had no booth, sponsorship or talk at the conference itself; it took part through side events: as a supporting partner of Banking the Agent Economy (6 Oct) and with Clément Lesaege on The Odds stage at the Agentic Finance Summit (8 Oct).', '{AI agents,Prediction markets,DeFi}', null, 'published'),
('agentic-finance-summit-the-odds', 'Agentic Finance Summit + The Odds: Prediction Markets Live', 'speaking', 'More & More, with The Odds', 'Side event', '2026-10-08', null, '14:00', 'GMT+8', 'Singapore', 'Singapore', 'Asia', 'Suntec Singapore Convention & Exhibition Centre, Level 3', 'https://luma.com/8oxs8lco', 'https://images.lumacdn.com/uploads/ta/a1b30c11-95f5-45f8-ae71-d10fc1f7b00e.png', 'A TOKEN2049 Singapore side event. Clément Lesaege closed The Odds stage at 17:00 on who decides how a prediction market resolves: oracles, arbiters and who has the final word, with Marcin (RedStone), Phillip Lord and CryptoKid.', '{Prediction markets,Oracles,Arbitration}', null, 'published'),
('proof-of-humanity-irl', 'Proof of Humanity: IRL', 'host', 'Kleros', 'Meetup', '2026-10-13', null, '18:00', 'GMT+7', 'Chiang Mai', 'Thailand', 'Asia', '4Seas Nimman Coliving Coworking Space', 'https://luma.com/6z1ed50q', 'https://images.lumacdn.com/uploads/95/df0b0261-1e3f-4d82-958a-70940415b913.jpg', 'Kleros hosted this introduction to Proof of Humanity, the registry that establishes each profile belongs to a unique human, with Wei Wei Ooi, Harmeet Singh and Karen Claire as hosts. The evening covered becoming a verified human, building the human trust network, and live help with registration.', '{Identity,Community,AI agents}', 'Good food, good conversations and new connections at 4Seas. Clément Lesaege closed the night with a talk on the Singularity: AI has passed humans on intelligence, is drawing level on taste, and trails on agency.', 'published'),
('the-future-is-tradable', 'The Future is Tradable', 'co_host', 'Kleros & Seer', 'Meetup', '2026-10-15', null, '18:00', 'GMT+7', 'Chiang Mai', 'Thailand', 'Asia', '4Seas Nimman Coliving Coworking Space', 'https://luma.com/v5nn24mq', 'https://images.lumacdn.com/uploads/14/79c65f99-1db3-4d98-97db-37c055b11ba5.jpg', 'An evening on prediction markets co-hosted by Kleros and Seer. Clément Lesaege spoke on markets as an information layer for humans and AI agents, and Juan Ramiro Garza on resolution: a market is only as good as the process that decides what happened. Wei Wei Ooi organized the event.', '{Prediction markets,AI agents,Oracles}', 'Six talks, from market probabilities to AI agents that trade for you. All six are below with their slides and subtitles.', 'published'),
('who-judges-the-machines-buenos-aires-2026', 'Who Judges the Machines? Law in the Age of Crowds and Algorithms', 'host', 'Kleros, with Parque de la Innovación', 'Side event', '2026-10-20', null, '18:30', 'GMT-3', 'Buenos Aires', 'Argentina', 'Latin America', 'Parque de la Innovación, Av. Guillermo Udaondo 1075, Núñez', null, 'https://pbs.twimg.com/media/HVL1JBAXsAApGCZ?format=jpg&name=large', 'An official Tecweek Buenos Aires side event organized by Kleros (¿Quién juzga a las máquinas?). Federico Ast opened with a keynote on who decides when two AI agents are in conflict, followed by two panels moderated by Sergio Mohadeb: one on regulating a world of agents with Alejandro H. Ramírez (IGJ), Darío Nieto and Pablo Palazzi, and one on legal practice with AI with Lorena Fabris, Ignacio Faillace (Lemon) and Facundo Trotz.', '{AI agents,Legal tech,Arbitration}', null, 'published'),
('ai-that-acts', 'AI That Acts: Inside the Agentic Economy', 'host', 'Kleros', 'Meetup', '2026-10-22', null, '18:00', 'GMT+7', 'Chiang Mai', 'Thailand', 'Asia', '4Seas Nimman Coliving Coworking Space', 'https://luma.com/clrlo1dj', 'https://images.lumacdn.com/uploads/t1/4b9a6f5b-266e-4e32-8b84-af2429b21413.jpg', 'Kleros hosted this evening on AI agents as economic actors, organized by Wei Wei Ooi with Harmeet Singh as co-host. Fortunato Cinquepalmi spoke on what happens when a deal between agents breaks, and Clément Lesaege on why the Singularity is near.', '{AI agents,Arbitration}', 'Two talks on what happens when AI stops assisting and starts acting. Fortunato Cinquepalmi on how agents act (once an agent pays, hires and decides for you, it needs an ID, a record and a court), with a live demo of a scooter shop agent billing for scratches already in its own photos. Clément Lesaege on why the Singularity is near.', 'published'),
('merge-madrid-2026', 'MERGE Madrid 2026', 'speaking', 'MERGE', 'Conference', '2026-10-28', null, null, 'GMT+1', 'Madrid', 'Spain', 'Europe', 'Palacio de Cibeles', null, 'https://pbs.twimg.com/media/HUcr8VlXgAAs9w7?format=jpg&name=large', 'Facundo Trotz speaks on the panel ''Agent Commerce: The New Generation of Payments'' (28 Oct, 15:40, MADRID Stage, AI x Blockchain track by QVAC), covering the dispute side of agent payments, with Vivek Chand (BSV), Sandro Knöpfel (Cardano Foundation) and Alberto Valero (Tether), moderated by Maxime Masuy (Mastercard).', '{AI agents,DeFi,Arbitration}', null, 'published'),
('devcon-8-mumbai', 'Devcon 8', 'speaking', 'Ethereum Foundation', 'Conference', '2026-11-03', '2026-11-06', null, 'GMT+5:30', 'Mumbai', 'India', 'Asia', 'Jio World Convention Centre', 'https://devcon.org', 'https://pbs.twimg.com/amplify_video_thumb/2105656777417031681/img/0fNInQG3F4PZu2xp.jpg?name=large', 'Kleros is a Devcon 8 supporter with a booth all four days. On the programme: Fortunato Cinquepalmi leads the Agentic Hub session ''Can We Trust the Machines? A Live Trial'' (3 Nov), Facundo Trotz and Federico Ast give short talks on 5 Nov (''What we learned bringing decentralized justice to Argentine citizens'' and ''See You in (Robot) Court: Justice in the Agent Economy''), and Clément Lesaege runs the workshop ''The Future of Prediction Markets is Decision Markets!'' with Devansh Mehta of Seer (6 Nov). Kleros also co-hosts the Legal & Governance Community Hub on 5 Nov and takes part in the Agentic and Prediction Markets hubs.', '{Arbitration,AI agents,Prediction markets,Governance}', null, 'published'),
('onchain-legal-summit-devcon-india', 'Onchain Legal Summit :: Devcon India 2026', 'co_host', 'Entity', 'Side event', '2026-11-04', null, '09:00', 'GMT+5:30', 'Mumbai', 'India', 'Asia', 'Jio World Convention Centre', 'https://luma.com/cw0h549b', 'https://images.lumacdn.com/uploads/hd/ce6ed4b8-bd25-40a7-aa3c-1a2a69b85de7.png', 'A Devcon 8 side event and the third Entity Onchain Legal Summit, after Devconnect Buenos Aires (2025) and Consensus Hong Kong (2026). Kleros is a co-host, with Wei Wei Ooi on the Luma host list. Topics include law as code, agent personhood and ERC-8004, decentralized justice and AI arbitration, and liability for borderless entities.', '{Legal tech,AI agents,Arbitration,Governance}', null, 'published'),
('ground-truth-mumbai', 'Truth Pays: Queryable Data, Prediction Markets & Onchain Justice', 'co_host', 'Kleros, Arkiv Network & Web3 Mumbai', 'Side event', '2026-11-04', null, '18:00', 'GMT+5:30', 'Mumbai', 'India', 'Asia', 'Hitchki (BKC)', 'https://luma.com/qewnqhas', 'https://images.lumacdn.com/uploads/r2/9b93fa27-4ea2-4c96-aee3-45a4f9ece400.jpg', 'A Devcon 8 side event: a networking dinner on queryable onchain data, prediction markets and decentralized justice on Ethereum, co-hosted by Kleros with Arkiv Network (by Golem) and Web3 Mumbai. Wei Wei Ooi is a Luma co-host.', '{Prediction markets,Oracles,Arbitration}', null, 'published'),
('austral-derecho-tecnologia-congreso-2026', 'II Congreso Internacional de Derecho y Tecnología aplicada a los Negocios (Universidad Austral)', 'speaking', 'Universidad Austral, Facultad de Derecho, with Universidad Complutense de Madrid', 'Conference', '2026-09-03', '2026-09-04', null, 'GMT-3', 'Buenos Aires', 'Argentina', 'Latin America', 'Universidad Austral, Cerrito 1250', 'https://www.colegio-escribanos.org.ar/2026/08/20/universidad-austral-segundo-congreso-internacional-de-derecho-y-tecnologia-aplicada-a-los-negocios/', 'https://abogados.com.ar/assets/img/articulos/2026-08-24-110521-segundo-congreso-internacional-de-derecho-y-tecnologia-3-y-4-septiembre-1.jpg', 'Facundo Trotz spoke on the international arbitration panel ''Jurisdicción y desafíos transfronterizos de la economía digital'' (4 Sep, 11:25) with Ana Elisa de Iparraguirre, Ariel Aginsky and Luciano Padín. Kleros was also a sponsor of the congress.', '{Arbitration,Legal tech}', null, 'published'),
('justicia-descentralizada-en-accion-webinar-2026', 'Justicia Descentralizada en Acción (Kleros Enterprise webinar)', 'host', 'Kleros Enterprise', 'Online talk / Space', '2026-05-11', null, '18:00', 'GMT-3', 'Online', null, 'Online', 'LinkedIn Live', 'https://www.linkedin.com/events/7457159172418236416/', 'https://pbs.twimg.com/card_img/2111375480683180032/MewMByAr?format=jpg&name=large', 'A Spanish-language webinar hosted by Kleros Enterprise on the Argentine pilots. Federico Ast moderated, with Judge María Fernanda Díaz (Lavalle), María Alejandra Tomasone (Junín consumer defence), Sergio Mohadeb (Derecho en Zapatillas), Marcos Pernas Machain and Lucía Bocalandro. Facundo Trotz gave the closing talk.', '{Legal tech,Arbitration}', null, 'published'),
('icc-france-crypto-arbitration-paris-2026', 'How to address the challenges of arbitration involving crypto-assets? (ICC France, Paris Arbitration Week)', 'speaking', 'ICC France', 'Panel', '2026-03-27', null, '10:30', 'GMT+1', 'Paris', 'France', 'Europe', 'd&a partners', 'https://parisarbitrationweek.com/event/icc-france-2026-41379/', 'https://pbs.twimg.com/media/HD3RhBaW8AAkDlR?format=jpg&name=large', 'During Paris Arbitration Week, Federico Ast spoke on Panel 2, ''Challenges in the Enforcement of Arbitral Awards'', with Sébastien Martin. Ast is part of the ICC France working group drafting rules for crypto-asset arbitration.', '{Arbitration,Legal tech}', null, 'published'),
('colorado-online-dispute-systems-workshop-2026', 'Online Dispute Systems Workshop (CU Boulder)', 'speaking', 'Nathan Schneider, Media Economies Design Lab, University of Colorado Boulder', 'Workshop', '2026-03-12', null, null, 'GMT-6', 'Boulder', 'USA', 'North America', 'University of Colorado Boulder', null, 'https://pbs.twimg.com/media/HDORFyYbQAcHogT?format=jpg&name=large', 'Federico Ast presented research on combining Kleros and AI into hybrid dispute resolution systems.', '{Arbitration,AI agents,Research}', null, 'published'),
('up-guadalajara-masterclass-2025', 'Masterclass: El Movimiento de la Justicia Descentralizada (Universidad Panamericana)', 'speaking', 'Universidad Panamericana Guadalajara', 'Academic', '2025-11-05', null, null, 'GMT-6', 'Guadalajara', 'Mexico', 'Latin America', 'Universidad Panamericana, campus Guadalajara', null, 'https://pbs.twimg.com/card_img/2112965427462615042/z9pjbrfP?format=jpg&name=large', 'Federico Ast gave the masterclass ''El Movimiento de la Justicia Descentralizada'' in the first week of November 2025.', '{Legal tech,Arbitration}', null, 'published'),
('champagnat-blockchain-justicia-mendoza-2025', 'Introducción al mundo Blockchain y la Justicia Descentralizada (Universidad Champagnat)', 'speaking', 'Juslab, Universidad Champagnat and Club Blockchain UCh', 'Academic', '2025-10-07', null, '18:00', 'GMT-3', 'Mendoza', 'Argentina', 'Latin America', 'Biblioteca Sede Central, Universidad Champagnat', null, 'https://pbs.twimg.com/media/G2CCc16WkAE8nlC?format=jpg&name=large', 'Marcos Pernas Machain and Facundo Trotz introduced blockchain and decentralized justice with Judge María Fernanda Díaz. The same trip included a visit to Lavalle and a workshop with secondary-school students.', '{Legal tech,Jurors}', null, 'published'),
('neuchatel-blockchain-dispute-resolution-2025', 'Blockchain Dispute Resolution: Wisdom of the Crowds vs. State Justice (LexTech Institute, Neuchâtel)', 'speaking', 'LexTech Institute, Université de Neuchâtel', 'Panel', '2025-05-21', null, null, 'GMT+2', 'Neuchâtel', 'Switzerland', 'Europe', 'Université de Neuchâtel', null, 'https://pbs.twimg.com/media/Gq1WGl2WMAAZatp?format=jpg&name=large', 'Federico Ast presented Kleros, followed by a panel moderated by Florence Guillaume with Judge Lino Hänni, Sven Riva (Schellenberg Wittmer) and Leonel Ferreira.', '{Arbitration,Legal tech}', null, 'published'),
('assas-legaltech-class-2025', 'Legaltech Program class (Université Paris-Panthéon-Assas)', 'speaking', 'Université Paris-Panthéon-Assas (Assas Future Law)', 'Academic', '2025-05-26', null, null, 'GMT+2', 'Paris', 'France', 'Europe', 'Université Paris-Panthéon-Assas', null, 'https://pbs.twimg.com/media/GsBtksWW0AA7KM6?format=jpg&name=large', 'Federico Ast gave his annual class in the Legaltech Program, in the week of 26 May 2025, on blockchain, smart contracts, company building and decentralized justice.', '{Legal tech,Smart contracts}', null, 'published')
